            _atomic(rpv_path(root), cur)
            e["state"] = "rolled_back"
        else:
            e["state"] = "superseded"
        e["closed_at"] = now.isoformat(timespec="seconds")
        done.append(e)
    if done:
        _atomic(log_path(root), log)
    return done


