        ref = f" {e['ref']}: {quote_text(e)}" if e.get("ref") else " слово владельца не названо"
        lines.append(f"• {at:%d.%m %H:%M} {e['key']}: {old} → {json.dumps(e['new'], ensure_ascii=False)} "
